+/**
+ * Sanitize embed content by parsing and reconstructing it safely
+ * This prevents HTML/JavaScript injection through srcdoc
+ */
+function sanitizeEmbedContent(content: string): string {
+  try {
+    // Parse the content as HTML
+    const parser = new DOMParser();
+    const doc = parser.parseFromString(content, "text/html");
+    
+    // Remove any script tags and event handlers
+    const scripts = doc.querySelectorAll("script");
+    scripts.forEach(script => script.remove());
+    
+    // Remove event handler attributes from all elements
+    const allElements = doc.querySelectorAll("*");
+    allElements.forEach(element => {
+      Array.from(element.attributes).forEach(attr => {
+        if (attr.name.toLowerCase().startsWith("on")) {
+          element.removeAttribute(attr.name);
+        }
+      });
+    });
+    
+    // Return the sanitized HTML
+    return doc.documentElement.innerHTML;
+  } catch (e) {
+    // If parsing fails, return empty string to prevent injection
+    return "";
+  }
+}
+
+/**
+ * Determine if an embed requires same-origin access
+ * Only specific trusted embed types should have this privilege
+ */
+function requiresSameOrigin(url: string): boolean {
+  // List of embed types that legitimately need same-origin access
+  const trustedEmbedPatterns = [
+    /^data:text\/html/,
+    // Add other trusted patterns as needed
+  ];
+  
+  return trustedEmbedPatterns.some(pattern => pattern.test(url));
+}

 export const isValidEmbedUrl = (url: string): boolean => {
   try {
     const sanitized = sanitizeUrl(url);
     return sanitized.length > 0;
   } catch {
     return false;
   }
 };

